  -- 'transactional' | 'marketing' | 'reorder' | 'coach_report' 等
  category      TEXT NOT NULL DEFAULT 'general',
  subject       TEXT NOT NULL,
  html_content  TEXT NOT NULL,
  text_content  TEXT NOT NULL,
  preheader     TEXT,
  is_active     INTEGER NOT NULL DEFAULT 1,
  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f', 'now', '+9 hours')),
  updated_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f', 'now', '+9 hours')),

  brand_id             TEXT REFERENCES brand_config(id) ON DELETE SET NULL);

-- from 042_email_channel.sql
CREATE TABLE IF NOT EXISTS email_messages_log (
  id                  TEXT PRIMARY KEY,
  subscriber_id       TEXT NOT NULL REFERENCES email_subscribers(id),
  template_id         TEXT REFERENCES email_templates(id),
  broadcast_id        TEXT REFERENCES broadcasts(id),
  scenario_step_id    TEXT REFERENCES scenario_steps(id),
  -- Phase 6 連携 (どの Shopify 注文が起点か)
  source_order_id     TEXT REFERENCES shopify_orders(id) ON DELETE SET NULL,
  -- 'reorder' | 'cross_sell' | 'broadcast' | 'transactional' | 'manual'
  source_kind         TEXT NOT NULL DEFAULT 'manual',
  -- 法令上の区分: 'transactional' | 'marketing'
  category            TEXT NOT NULL DEFAULT 'marketing',
  subject             TEXT NOT NULL,
  from_address        TEXT NOT NULL,
  reply_to            TEXT,
  -- provider 情報
  provider            TEXT NOT NULL,
  provider_message_id TEXT,
  -- 状態: 'queued' | 'sent' | 'delivered' | 'opened' | 'clicked' | 'bounced' | 'complained' | 'failed'
  status              TEXT NOT NULL DEFAULT 'queued',
  error_summary       TEXT,
  sent_at             TEXT,
  delivered_at        TEXT,
  first_opened_at     TEXT,
  last_event_at       TEXT,
  open_count          INTEGER NOT NULL DEFAULT 0,
  click_count         INTEGER NOT NULL DEFAULT 0,
  created_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f', 'now', '+9 hours'))
);

-- from 042_email_channel.sql
CREATE TABLE IF NOT EXISTS email_link_clicks (
  id            TEXT PRIMARY KEY,
  email_log_id  TEXT NOT NULL REFERENCES email_messages_log(id),
  url           TEXT NOT NULL,
  clicked_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f', 'now', '+9 hours')),
  user_agent    TEXT,
  -- IP は SHA-256 で hash 化して保存 (個人情報最小化)
  ip_hash       TEXT
);

-- from 047_brand_config.sql
CREATE TABLE IF NOT EXISTS brand_config (
  id                  TEXT PRIMARY KEY,
  -- NULL = default brand (system-wide fallback)、 値あり = account-specific brand
  line_account_id     TEXT REFERENCES line_accounts(id) ON DELETE CASCADE,
  -- 1 行のみ is_default=1 (UNIQUE WHERE で保証)
  is_default          INTEGER NOT NULL DEFAULT 0,
  -- 表示名 / 法人名 / 連絡先
  brand_name          TEXT NOT NULL,
  company_name        TEXT,
  support_email       TEXT,
  -- ストア URL 系
  shop_url            TEXT,
  subscription_url    TEXT,
  -- 視覚 (LINE 緑系がデフォルト)
  primary_color       TEXT NOT NULL DEFAULT '#06C755',
  -- welcome 等で紹介する代表商品ラベル
  intro_product_label TEXT,
  logo_url            TEXT,
  -- 拡張用 JSON (industry / plan / 業種固有設定 等)
  metadata            TEXT NOT NULL DEFAULT '{}',
  created_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f', 'now', '+9 hours')),
  updated_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f', 'now', '+9 hours'))
);

-- from 048_audit_logs.sql
CREATE TABLE IF NOT EXISTS audit_logs (
  id              TEXT PRIMARY KEY,
  -- multi-tenant (NULL = system-wide)
  line_account_id TEXT REFERENCES line_accounts(id) ON DELETE SET NULL,
  -- 'admin' | 'system' | 'cron' | 'webhook' | 'api'
  actor_type      TEXT NOT NULL,
  -- admin user id / cron job id 等。 NULL = anonymous system
  actor_id        TEXT,
  -- 操作時点の actor 表示名 snapshot (削除されても判別可)
  actor_name      TEXT,
  -- 'broadcast.send' / 'friend.delete' / 'template.update' 等の dot-notation
  action          TEXT NOT NULL,
  -- 'broadcast' / 'friend' / 'template' / 'automation' 等
  target_type     TEXT,
  target_id       TEXT,
  -- 1 リクエストにまたがる複数 audit を結合する trace ID
  request_id      TEXT,
  -- IP は SHA-256 hash で保存 (PII 最小化)
  ip_hash         TEXT,
  user_agent      TEXT,
  -- 操作前/後の値 snapshot (JSON 文字列、 destructive 操作で重要)
  before_value    TEXT,
  after_value     TEXT,
  -- 'success' | 'failure'
  result          TEXT NOT NULL DEFAULT 'success',
  -- failure 時の概要 (詳細は metadata に)
  error_message   TEXT,
  -- 拡張 (request body summary / 影響レコード数 等)
  metadata        TEXT NOT NULL DEFAULT '{}',
  created_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f', 'now', '+9 hours'))
);

-- from 050_line_friend_coupons.sql
CREATE TABLE IF NOT EXISTS line_friend_coupons (
  id                       TEXT PRIMARY KEY,
  friend_id                TEXT NOT NULL UNIQUE,           -- 1 friend に 1 coupon (初回のみ)
  line_account_id          TEXT,
  coupon_code              TEXT NOT NULL,                  -- Shopify で発行された code (顧客が入力する文字列)
  shopify_discount_code_id TEXT,                           -- Shopify GraphQL ID (gid://shopify/DiscountCodeBasic/...)
  shopify_price_rule_id    TEXT,                           -- Shopify Price Rule ID (legacy REST、 将来更新可)
  discount_value           INTEGER NOT NULL,               -- 値引き額 (整数、 例: 500)
  discount_currency        TEXT NOT NULL DEFAULT 'JPY',
  issued_at                TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f', 'now', '+9 hours')),
  redeemed_at              TEXT,                            -- 使用された時刻 (将来 Shopify webhook で更新)
  expires_at               TEXT,                            -- coupon 有効期限 (NULL = 無期限)
  status                   TEXT NOT NULL DEFAULT 'issued'
                           CHECK (status IN ('issued', 'redeemed', 'expired', 'revoked')),
  source                   TEXT NOT NULL DEFAULT 'shopify'
                           CHECK (source IN ('shopify', 'static_fallback')),
  metadata                 TEXT,                            -- JSON (Shopify API response の subset 等)
  FOREIGN KEY (friend_id) REFERENCES friends(id) ON DELETE CASCADE,
  FOREIGN KEY (line_account_id) REFERENCES line_accounts(id) ON DELETE SET NULL
);

-- from 054_ai_models_catalog.sql
CREATE TABLE IF NOT EXISTS ai_models_catalog (
  id                   TEXT PRIMARY KEY,
  model_id             TEXT NOT NULL UNIQUE,
  vendor               TEXT NOT NULL,
  family               TEXT NOT NULL,
  size_label           TEXT,
  task                 TEXT NOT NULL,
  capabilities         TEXT,
  context_window       INTEGER,
  description          TEXT,
  is_beta              INTEGER NOT NULL DEFAULT 0,
  is_deprecated        INTEGER NOT NULL DEFAULT 0,
  primary_candidate    INTEGER NOT NULL DEFAULT 0,
  fallback_candidate   INTEGER NOT NULL DEFAULT 0,
  first_seen_at        TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f', 'now', '+9 hours')),
  last_seen_at         TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f', 'now', '+9 hours')),
  last_synced_at       TEXT,
  raw_metadata         TEXT,
  source               TEXT NOT NULL DEFAULT 'seed',
  created_at           TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f', 'now', '+9 hours')),
  updated_at           TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f', 'now', '+9 hours'))
);

-- from 055_changelog_entries.sql
CREATE TABLE IF NOT EXISTS changelog_entries_seen (
  id             TEXT PRIMARY KEY,
  entry_url      TEXT NOT NULL UNIQUE,
  title          TEXT NOT NULL,
  category       TEXT NOT NULL,
  published_at   TEXT,
  first_seen_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f', 'now', '+9 hours')),
  notified_at    TEXT,
  description    TEXT
);

-- from 056_google_merchant_audit.sql
CREATE TABLE IF NOT EXISTS google_merchant_audit_runs (
  id                  TEXT PRIMARY KEY,
  run_at              TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f', 'now', '+9 hours')),
  trigger             TEXT NOT NULL,            -- 'cron' / 'manual' / 'admin-ui'
  status              TEXT NOT NULL,            -- 'success' / 'partial' / 'error'
  total_products      INTEGER NOT NULL DEFAULT 0,
  products_with_issues INTEGER NOT NULL DEFAULT 0,
  high_severity_count INTEGER NOT NULL DEFAULT 0,
  medium_severity_count INTEGER NOT NULL DEFAULT 0,
  low_severity_count  INTEGER NOT NULL DEFAULT 0,
  issues_by_category  TEXT,                     -- JSON: { ng_keyword: 3, missing_gtin: 12, ... }
  duration_ms         INTEGER,
  error_message       TEXT,
  created_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f', 'now', '+9 hours'))
);

-- from 056_google_merchant_audit.sql
CREATE TABLE IF NOT EXISTS product_audit_issues (
  id                  TEXT PRIMARY KEY,
  run_id              TEXT NOT NULL,            -- google_merchant_audit_runs.id
  shopify_product_id  TEXT NOT NULL,            -- gid://shopify/Product/123
  product_title       TEXT NOT NULL,
  product_handle      TEXT,
  category            TEXT NOT NULL,            -- 'ng_keyword' / 'missing_gtin' / 'missing_gpc' / 'missing_brand' / 'image_overlay_suspected' / 'price_inconsistency' / 'inventory_zero' / 'missing_description'
  severity            TEXT NOT NULL,            -- 'high' / 'medium' / 'low'
  field               TEXT,                     -- 'title' / 'description' / 'metafield.google.identifier_exists' / etc.
  original_value      TEXT,                     -- before fix
  suggested_value     TEXT,                     -- recommended fix
  applied             INTEGER NOT NULL DEFAULT 0, -- 0 = pending, 1 = applied
  applied_at          TEXT,
  applied_by          TEXT,                     -- 'auto' / 'admin-ui' / user-id
  metadata            TEXT,                     -- JSON for extra context (= ng_pattern matched, etc.)
  created_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f', 'now', '+9 hours'))
);

-- from 058_membership_tiers.sql
CREATE TABLE IF NOT EXISTS membership_tiers (
  id                    TEXT PRIMARY KEY,                -- e.g. 'bronze', 'silver'
  name                  TEXT NOT NULL,                   -- 表示名 (= 「ブロンズ」 「シルバー」)
  display_order         INTEGER NOT NULL,                -- sort order (= 1=bronze, 2=silver, ...)
  min_total_purchase_jpy INTEGER NOT NULL DEFAULT 0,     -- 累計購入額の閾値 (= 円)
  min_referral_count    INTEGER NOT NULL DEFAULT 0,      -- 紹介人数の閾値 (= alternative path)
  perks                 TEXT,                            -- JSON: { discount_percent: 5, exclusive_products: [], priority_support: false, ... }
  badge_emoji           TEXT,                            -- LIFF 表示用絵文字 (= 🥉 / 🥈 / 🥇 / 💎)
  badge_color           TEXT,                            -- hex color (= UI tinting 用)
  is_active             INTEGER NOT NULL DEFAULT 1,      -- 0/1
  created_at            TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f', 'now', '+9 hours')),
  updated_at            TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f', 'now', '+9 hours'))
);

-- from 058_membership_tiers.sql
CREATE TABLE IF NOT EXISTS members (
  id                    TEXT PRIMARY KEY,
  friend_id             TEXT NOT NULL UNIQUE,            -- friends.id FK
  current_tier_id       TEXT NOT NULL DEFAULT 'bronze',  -- membership_tiers.id FK
  total_purchase_jpy    INTEGER NOT NULL DEFAULT 0,      -- 累計購入額 (= Shopify 連動で更新)
  total_referral_count  INTEGER NOT NULL DEFAULT 0,      -- 紹介成功人数 (= referral_codes でカウント)
  last_purchase_at      TEXT,                            -- 最終購入時刻
  last_promotion_at     TEXT,                            -- 最終 tier 昇格時刻
  joined_at             TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f', 'now', '+9 hours')),
  created_at            TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f', 'now', '+9 hours')),
  updated_at            TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f', 'now', '+9 hours'))
);

-- from 059_member_purchase_events.sql
CREATE TABLE IF NOT EXISTS member_purchase_events (
  id                TEXT PRIMARY KEY,
  shopify_order_id  TEXT NOT NULL UNIQUE,           -- Shopify order ID (= 冪等性 key)
  friend_id         TEXT,                            -- friends.id FK (= NULL ならマッチ失敗 audit only)
  amount_jpy        INTEGER NOT NULL DEFAULT 0,      -- 注文金額 (= 円)
  currency          TEXT NOT NULL DEFAULT 'JPY',
  order_number      INTEGER,                         -- Shopify order_number (= 人間可読)
  email             TEXT,                            -- order email (= マッチ失敗時の debug 用)
  phone             TEXT,                            -- order phone (= 同上)
  applied_at        TEXT,                            -- members への加算実行時刻 (NULL なら未適用)
  source            TEXT NOT NULL DEFAULT 'webhook', -- 'webhook' | 'backfill' | 'manual'
  metadata          TEXT,                            -- JSON: raw fields for debug
  created_at        TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f', 'now', '+9 hours')),
  updated_at        TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f', 'now', '+9 hours')),

  occurred_at          TEXT);

-- from 061_loyalty_rank_snapshots.sql
CREATE TABLE IF NOT EXISTS loyalty_rank_snapshots (
  id                 TEXT PRIMARY KEY,
  friend_id          TEXT NOT NULL,                   -- friends.id
  period             TEXT NOT NULL,                   -- 'YYYY-MM' (= 評価対象月、 同月冪等 key)
  rank_id            TEXT NOT NULL,                   -- regular/bronze/silver/gold/platinum
  trailing_12mo_jpy  INTEGER NOT NULL DEFAULT 0,      -- 算出時の trailing-12ヶ月 購入額
  prev_rank_id       TEXT,                            -- 前 snapshot の rank (= 降格/昇格検知)
  direction          TEXT NOT NULL DEFAULT 'initial', -- 'initial' | 'up' | 'down' | 'same'
  brand_id           TEXT,                            -- multi-brand (= NULL は naturism default)
  evaluated_at       TEXT NOT NULL,                   -- 算出時点 (JST)
  created_at         TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f', 'now', '+9 hours')),
  UNIQUE(friend_id, period)
);

-- from 062_loyalty_rank_discounts.sql
CREATE TABLE IF NOT EXISTS loyalty_rank_discounts (
  id                       TEXT PRIMARY KEY,
  friend_id                TEXT NOT NULL,                   -- friends.id
  rank_id                  TEXT NOT NULL,                   -- bronze/silver/gold/platinum (= regular は発行しない)
  code                     TEXT NOT NULL UNIQUE,            -- NLR-{RANK}-{suffix}
  shopify_discount_node_id TEXT,                            -- gid://shopify/DiscountCodeNode/...
  discount_percent         INTEGER NOT NULL DEFAULT 0,      -- 2/4/6/8
  status                   TEXT NOT NULL DEFAULT 'active',  -- 'active' | 'superseded'
  brand_id                 TEXT,                            -- multi-brand (= NULL は naturism default)
  issued_at                TEXT NOT NULL,                   -- 発行時刻 (JST ISO)
  expires_at               TEXT,                            -- NULL=無期限 (= 既定は ~45日で再発行)
  superseded_at            TEXT,                            -- supersede 時刻
  created_at               TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f', 'now', '+9 hours'))
);

-- from 064_account_link_codes.sql
CREATE TABLE IF NOT EXISTS account_link_codes (
  id TEXT PRIMARY KEY,
  friend_id TEXT NOT NULL,
  email TEXT NOT NULL,                 -- lowercased 受信者 email (= 本人入力)
  code_hash TEXT NOT NULL,             -- HMAC-SHA256(pepper, "friend_id:email:code") hex
  expires_at TEXT NOT NULL,            -- ISO8601 (= now + TTL)
  attempts INTEGER NOT NULL DEFAULT 0, -- verify 試行回数 (= MAX 到達で lock)
  consumed_at TEXT,                    -- single-use: 成功 / lock / 旧 code 無効化 で埋まる
  created_at TEXT NOT NULL
);

-- from 066_webhook_deliveries.sql
CREATE TABLE IF NOT EXISTS webhook_deliveries (
  webhook_event_id TEXT PRIMARY KEY,  -- LINE event の一意 ID (= 冪等 key)
  created_at TEXT NOT NULL             -- ISO8601 (UTC) 受信時刻 (= TTL prune 用)
);

-- from 068_line_referral_coupons.sql
CREATE TABLE IF NOT EXISTS line_referral_coupons (
  id                       TEXT PRIMARY KEY,
  friend_id                TEXT NOT NULL,                   -- referrer (= 紹介した側、 報酬クーポンの所有者)
  reward_id                TEXT NOT NULL,                   -- referral_rewards.id (= 紹介成立1件。 冪等キー)
  role                     TEXT NOT NULL DEFAULT 'referrer'
                           CHECK (role IN ('referrer', 'referred')),
  coupon_code              TEXT NOT NULL,                  -- Shopify で発行された code
  shopify_discount_code_id TEXT,                           -- Shopify GraphQL ID (gid://shopify/DiscountCodeNode/...)
  discount_value           INTEGER NOT NULL DEFAULT 500,
  discount_currency        TEXT NOT NULL DEFAULT 'JPY',
  issued_at                TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f', 'now', '+9 hours')),
  expires_at               TEXT,                            -- coupon 有効期限 (NULL = 無期限)
  redeemed_at              TEXT,                            -- 使用時刻 (将来 orders webhook で更新)
  status                   TEXT NOT NULL DEFAULT 'issued'
                           CHECK (status IN ('issued', 'redeemed', 'expired', 'revoked')),
  line_account_id          TEXT,
  metadata                 TEXT,                            -- JSON (Shopify API response の subset 等)
  FOREIGN KEY (friend_id) REFERENCES friends(id) ON DELETE CASCADE,
  FOREIGN KEY (line_account_id) REFERENCES line_accounts(id) ON DELETE SET NULL,
  -- 紹介成立 (referral_rewards) 1 件につき referrer クーポン 1 枚 = 冪等キー。
  -- referrer は「何度でも紹介でき、 紹介先が購入するたびに ¥500」= friend_id では UNIQUE にしない
  -- (= 1 referrer が複数の reward で複数クーポンを持てる)。
  UNIQUE (reward_id)
);

-- from 069_subscription_contracts.sql
CREATE TABLE IF NOT EXISTS subscription_contracts (
  contract_id TEXT PRIMARY KEY,               -- 注文タグ subscription-id:{ID} の値
  shopify_customer_id TEXT,                   -- shopify_customers / friends.shopify_customer_id と照合
  plan_name TEXT,                             -- selling plan 名 or 顧客タグ subscription-{ID}-plan の値
  interval_days INTEGER,                      -- plan 名から解析 (「30日に1回配送」→30)。解析不能は NULL
  order_count INTEGER,                        -- 注文タグ subscription-count:{N} (最新値)
  last_order_id TEXT,                         -- shopify_orders.shopify_order_id
  last_order_at TEXT,                         -- 直近の定期注文作成 (≈決済) 日時
  last_delivery_date TEXT,                    -- 注文タグ delivery-{ID}:{yyyy-mm-dd ...} の日付部
  skip_count INTEGER NOT NULL DEFAULT 0,      -- 顧客タグ subscription-{ID}-skip-count:{n} (累計)
  skip_count_at_last_order INTEGER NOT NULL DEFAULT 0, -- 直近注文時点の skip 累計 (推定日計算用)
  paused_at TEXT,                             -- 顧客タグ subscription-{ID}-pause:{date} (決済失敗も含む)
  cancelled_at TEXT,                          -- 顧客タグ subscription-{ID}-cancel:{date}
  next_billing_estimate TEXT,                 -- YYYY-MM-DD (JST)。cancelled/paused/interval不明は NULL
  estimate_source TEXT NOT NULL DEFAULT 'derived', -- derived | flow (WI-2 で Shopify Flow 実測に昇格)
  reminded_for_estimate TEXT,                 -- WI-2 リマインド冪等キー (この推定日に送信済み)
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),

  recovery_pending_at  TEXT,
  recovery_notified_at TEXT,
  flow_estimate_anchor TEXT,
  skip_count_at_estimate INTEGER NOT NULL DEFAULT 0,
  flow_measured_at     TEXT);

-- from 071_own_billing_foundation.sql
CREATE TABLE IF NOT EXISTS own_sub_contracts (
  contract_gid        TEXT PRIMARY KEY,
  shopify_customer_id TEXT NOT NULL,
  status              TEXT NOT NULL,          -- active|paused|cancelled|expired|failed
  current_cycle_index INTEGER,                -- 最古の未解決サイクル (§4.0)
  current_cycle_scheduled_date TEXT,          -- scheduleEdit 済み課金予定日 (JST)
  anchor_date         TEXT NOT NULL,          -- カデンツ起点 (承継課金日 or 初回課金日)
  interval_unit       TEXT NOT NULL,          -- 'DAY' のみサポート (§0)
  interval_count      INTEGER NOT NULL,
  payment_method_gid  TEXT,
  pending_new_card    INTEGER NOT NULL DEFAULT 0,  -- challenged 中のカード更新フラグ (§6.3)
  cadence_repair_needed INTEGER NOT NULL DEFAULT 0, -- scheduleEdit 失敗の修復待ち (§4.0)
  dunning_state       TEXT NOT NULL DEFAULT 'none',
      -- none|retry_wait|await_card|challenged|ops_hold|exhausted
  dunning_attempts    INTEGER NOT NULL DEFAULT 0,
  next_retry_date     TEXT,
  dunning_deadline_at TEXT,                   -- await_card / challenged の期限 (§6.2/§6.3)
  last_attempt_error  TEXT,                   -- code のみ (PII なし)
  source              TEXT NOT NULL,          -- migration|new
  created_at          TEXT NOT NULL,
  updated_at          TEXT NOT NULL
);

-- from 071_own_billing_foundation.sql
CREATE TABLE IF NOT EXISTS billing_cycle_claims (
  contract_gid    TEXT NOT NULL,
  cycle_key       TEXT NOT NULL,              -- Shopify cycle_index
  status          TEXT NOT NULL,
      -- attempting|succeeded|failed|failed_no_attempt|skipped|abandoned
  retry_policy    TEXT NOT NULL DEFAULT 'none', -- none|next_tick|hold (§6.5)
  attempt_no      INTEGER NOT NULL DEFAULT 1,
  attempt_gid     TEXT,
  order_id        TEXT,                       -- success 時に記録 (双方向突合の連結キー)
  idempotency_key TEXT NOT NULL,              -- SHA-256("own-billing:{gid}:{cycle_key}:{attempt_no}")
  claimed_at      TEXT NOT NULL,
  resolved_at     TEXT,
  PRIMARY KEY (contract_gid, cycle_key)
);

-- from 071_own_billing_foundation.sql
CREATE TABLE IF NOT EXISTS sub_migration_snapshots (
  huckleberry_contract_id TEXT PRIMARY KEY,
  shopify_customer_id TEXT NOT NULL,
  snapshot_json       TEXT NOT NULL,          -- 全条件 + Flow 実測 + 直近 order_id
  own_contract_gid    TEXT,
  phase               TEXT NOT NULL,
      -- snapshotted|pending_card|own_created_paused|hb_stop_requested|
      -- huckleberry_stopped|billing_aligned|activated|rolled_back
  target_first_billing_date TEXT,             -- billing_aligned が確定する絶対日付
  pending_intent      TEXT,                   -- NULL|'pause'|'cancel' (§7.0)
  pending_intent_done INTEGER NOT NULL DEFAULT 0,
  phase_updated_at    TEXT NOT NULL,
  created_at          TEXT NOT NULL
);

-- from 071_own_billing_foundation.sql
CREATE TABLE IF NOT EXISTS own_billing_notices (
  contract_gid TEXT NOT NULL,
  cycle_key    TEXT NOT NULL,
  attempt_no   INTEGER NOT NULL,
  kind         TEXT NOT NULL,
  sent_at      TEXT NOT NULL,
  PRIMARY KEY (contract_gid, cycle_key, attempt_no, kind)
);

-- from 071_own_billing_foundation.sql
CREATE TABLE IF NOT EXISTS own_billing_state (
  key        TEXT PRIMARY KEY,
  value      TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

-- from 071_own_billing_foundation.sql
CREATE TABLE IF NOT EXISTS own_billing_quarantine (
  contract_gid TEXT PRIMARY KEY,
  reason       TEXT NOT NULL,
  added_at     TEXT NOT NULL
);

-- from 072_own_billing_notice_queue.sql
CREATE TABLE IF NOT EXISTS own_billing_notice_queue (
  id                INTEGER PRIMARY KEY AUTOINCREMENT,
  contract_gid      TEXT NOT NULL,
  cycle_key         TEXT NOT NULL,
  attempt_no        INTEGER NOT NULL,
  kind              TEXT NOT NULL,
      -- fail_notice|card_request|challenge_link|pause_notice|resume_notice|delivery_notice
  shopify_customer_id TEXT NOT NULL,
  payload_json      TEXT NOT NULL,   -- 文面組立パラメータ (PII 最小: 金額/日付/URL のみ)
  status            TEXT NOT NULL DEFAULT 'queued',
      -- queued|sending|sent|failed|abandoned
  channel           TEXT,            -- line|email (確定時に記録)
  dispatch_attempts INTEGER NOT NULL DEFAULT 0,
  last_error        TEXT,            -- 分類済みの短い理由のみ (PII なし)
  queued_at         TEXT NOT NULL,
  -- 'sending' へ CAS した時刻。**reaper はこの列で判定する**。
  -- queued_at で判定すると、配送窓 (JST10-20) と enqueue 時刻の差により拾った瞬間から
  -- reap 対象になり、排他が実質無効化されて同じ通知を 2 通送りうる。
  sending_at        TEXT,
  sent_at           TEXT,
  UNIQUE (contract_gid, cycle_key, attempt_no, kind)
);

-- from 073_sub_link_tokens.sql
CREATE TABLE IF NOT EXISTS sub_link_tokens (
  token TEXT PRIMARY KEY,                 -- 160bit base64url ランダム (= link の capability)
  shopify_customer_id TEXT NOT NULL,      -- 連携先 Shopify customer (= redeem で friends に紐付ける対象)
  batch_id TEXT NOT NULL,                 -- 生成バッチ ID (= キャンペーン単位のグルーピング/集計)
  expires_at TEXT NOT NULL,               -- ISO8601 (= now + TTL)。 preview/redeem は過去なら拒否
  consumed_at TEXT,                       -- single-use CAS (NULL → now)。 消費済は再利用不可
  consumed_by_line_user_id TEXT,          -- 監査: 消費した検証済 LINE userId
  consumed_friend_id TEXT,                -- 監査: 実際に紐付いた friend 行
  created_at TEXT NOT NULL
);

-- from 076_sub_intents.sql
CREATE TABLE IF NOT EXISTS sub_intents (
  id TEXT PRIMARY KEY,                          -- 'si_' + 128bit crypto ランダム (service 層が採番)
  friend_id TEXT,                               -- 受理時点の friend (未連携顧客のスタッフ代理受理は NULL)
  contract_ns TEXT NOT NULL,                    -- 'hb' | 'own' (移行境界を跨ぐので名前空間必須 §1)
  contract_key TEXT NOT NULL,                   -- ns='hb' → huckleberry contract_id / ns='own' → own contract gid
  target_cycle_key TEXT NOT NULL,               -- 提示時のサイクル識別子 '{contract_key}:{YYYY-MM-DD|unknown}'
  presented_scheduled_date TEXT,                -- 提示時に画面へ出した予定日 (受理時に現在値と突合する §1)
  op TEXT NOT NULL,                             -- skip|date|pause|resume|cancel|undo_of
  state TEXT NOT NULL DEFAULT 'received',       -- 上記 9 state
  requested_by TEXT NOT NULL,                   -- customer|staff|system (種別。§1-4 で自動 pause と分離)
  actor_staff_id TEXT,                          -- 最終遷移の個人 (受理・実行・却下で更新。全履歴は audit_logs)
  actor_role TEXT,
  payload_json TEXT,                            -- 依頼パラメータ (op='date' の希望日等)。PII を書かない
  deadline_at TEXT,                             -- 変更受付期限 (= 決済日の 3 日前 EOD JST)。NULL = 締切なし
  promised_by TEXT,                             -- §4-1 の約束期限 (§10-4 で使用。本 migration では列のみ)
  claimed_at TEXT,                              -- executing の claim 時刻。/admin/ops が未解決時間を常時表示
  executor TEXT NOT NULL DEFAULT 'human',       -- human|own_billing|api|blocked
  supersedes_intent_id TEXT,                    -- undo_of が指す元 intent
  fail_reason TEXT,                             -- failed の理由 (deadline_passed|cycle_drift|staff 入力等)
  carryover_count INTEGER NOT NULL DEFAULT 0,   -- pause/cancel の繰越し回数 (可視化・無限ループ検知)
  escalated_at TEXT,                            -- 締切超過エスカレーション済みマーカー (1 intent 1 回 §4-2)
  stale_alerted_at TEXT,                        -- claim 滞留アラート済みマーカー (claim 世代ごと §1-2。
                                                --  claim/release でクリア = escalated_at と目的を分離し、
                                                --  片方の消費でもう片方が沈黙しないようにする)
  created_at TEXT NOT NULL,
  resolved_at TEXT                              -- terminal 到達時刻 (done/expired/failed/cancelled/superseded)
);

